function aiEvidenceRows(items=[], key='quote'){
 return (Array.isArray(items)?items:[]).slice(0,30).map(item=>`<div class="ai-evidence-row"><b>第 ${esc(item.page??'?')} 页</b><span>${esc(item[key]||item.quote||'')}</span><small>${esc(item.support||item.confidence||'待核验')}</small></div>`).join('');
}
function aiVisualRows(items=[]){
  return (Array.isArray(items)?items:[]).slice(0,40).map(item=>`<div class="ai-visual-row"><div class="ai-visual-head"><b>${esc(item.type||'视觉对象')}</b><span>第 ${esc(item.page??'?')} 页 · ${esc(item.confidence||'待核验')}</span></div><p>${esc(item.description||item.claim||'')}</p>${item.transcription_latex?`<code>${esc(item.transcription_latex)}</code>`:''}${item.data_relationships?`<small>关系：${esc(item.data_relationships)}</small>`:''}</div>`).join('');
}
function aiVisualPanel(data, analysis={}){
  const visual=analysis.visual_analysis||{};const evidence=analysis.visual_evidence||analysis.visual_observations||[];
  const groups=[['公式',visual.formulas],['图与曲线',visual.figures],['表格',visual.tables],['流程图/示意图',visual.diagrams]];
  const groupHtml=groups.filter(([,value])=>value&&((Array.isArray(value)&&value.length)||(!Array.isArray(value)&&String(value).trim()))).map(([label,value])=>`<div class="ai-visual-group"><b>${label}</b>${Array.isArray(value)?`<ul>${value.slice(0,20).map(item=>`<li>${esc(typeof item==='string'?item:JSON.stringify(item))}</li>`).join('')}</ul>`:`<p>${esc(value)}</p>`}</div>`).join('');
  const failures=(data.visual_failures||[]).length;const status=data.visual_requested?(data.visual_pages?`已视觉核验 ${esc(data.visual_pages)} 页`:'未成功渲染视觉页'):'未启用视觉页';
  const refs=data.visual_page_refs||[];const refHtml=refs.length?`<div class="ai-visual-page-links">${refs.slice(0,20).map(item=>`<a href="${esc(item.url||item.pdf_url||'#')}" target="_blank" rel="noopener">查看第 ${esc(item.page||'?')} 页图像 ↗</a>`).join('')}</div>`:'';
  return `<div class="ai-visual-panel"><div class="ai-subtitle">公式、图表与图像识别 · ${status}</div>${failures?`<div class="ai-quality-warning">有 ${esc(failures)} 个视觉处理限制；无法确认的公式或图表不会被当作事实，请回看原 PDF。</div>`:''}${refHtml}${groupHtml?`<div class="ai-visual-grid">${groupHtml}</div>`:''}${evidence.length?`<div class="ai-subtitle">视觉证据锚点</div><div class="ai-visual-list">${aiVisualRows(evidence)}</div>`:''}</div>`;
}
function aiDeepStructuredPanel(data, analysis={}){
  const problem=analysis.problem_formulation||{};const equation=analysis.equation_analysis||[];const steps=analysis.method?.algorithm_steps||[];const tables=analysis.result_tables||[];
  const value=(item,key)=>esc(typeof item==='string'?item:(item?.[key]||JSON.stringify(item)));
  const block=(title,body)=>body?`<div class="ai-deep-structured"><div class="ai-subtitle">${title}</div>${body}</div>`:'';
  const problemBody=Object.entries(problem).filter(([,v])=>v!==undefined&&v!==null&&String(v).trim()).map(([key,v])=>`<div class="ai-structured-line"><b>${esc(key)}</b><span>${esc(Array.isArray(v)?v.join('；'):typeof v==='object'?JSON.stringify(v):v)}</span></div>`).join('');
  const stepsBody=Array.isArray(steps)&&steps.length?`<ol>${steps.map(item=>`<li>${value(item,'description')}</li>`).join('')}</ol>`:'';
  const equationBody=Array.isArray(equation)&&equation.length?equation.map(item=>`<div class="ai-equation-row"><b>${esc(item.name||((item.page||item.page===0)?`第 ${item.page||'?'} 页`:'公式'))}</b><code>${esc(item.latex||item.transcription_latex||'')}</code><p>${esc(item.explanation||item.role||item.variables||JSON.stringify(item))}</p></div>`).join(''):'';
  const tableBody=Array.isArray(tables)&&tables.length?`<div class="ai-result-table-list">${tables.map(item=>`<div class="ai-result-table-row"><b>${esc(item.name||item.title||`第 ${item.page||'?'} 页`)}</b><span>${esc(item.summary||item.comparison||item.data||JSON.stringify(item))}</span></div>`).join('')}</div>`:'';
  return `<div class="ai-deep-structured-panel">${block('问题形式化',problemBody?`<div class="ai-structured-grid">${problemBody}</div>`:'')} ${block('算法/方法步骤',stepsBody)} ${block('公式与变量解析',equationBody)} ${block('结果表格与数值关系',tableBody)}</div>`;
}
function renderAiReadingCard(data, target){
 const draft=data?.draft||data?.analysis?.reading_card||data?.analysis||{};const evidence=data?.analysis?.evidence||data?.evidence||[];
  const applied=Boolean(data?.applied||data?.auto_applied);const artifactId=data.artifact_id||data.id||'';
  const timing=data?.duration_ms?` · ${Math.round(Number(data.duration_ms)/1000)} 秒 · ${data.model_call_count||'?'} 次模型请求`:'';
  target.innerHTML=`<div class="ai-meta">全文阅读卡 · ${esc(data?.page_count||'')} 页 · ${esc(data?.model||'模型')} · ${esc(fmtDate(data?.created_at,true))}${timing} ${applied?'<span class="evaluation-status">已自动填充空字段</span>':''}</div>${data?.low_quality_pages?`<div class="ai-quality-warning">有 ${esc(data.low_quality_pages)} 个低质量或空白页，相关结论可能不完整，请重点核对 PDF。</div>`:''}<div class="ai-card-grid">${Object.entries(READING_CARD_FIELDS).map(([key,label])=>`<div class="ai-card-item"><b>${esc(label)}</b><p>${esc(draft[key]||'原文未说明')}</p></div>`).join('')}</div>${evidence.length?`<div class="ai-subtitle">页码证据</div><div class="ai-evidence-list">${aiEvidenceRows(evidence)}</div>`:''}${aiVisualPanel(data,data?.analysis||{})}<div class="ai-actions">${applied?'<span class="ai-hint">已有人工内容已保留；本次结果只填充原本为空的字段，并已建立历史版本。</span>':`<button class="button small" data-apply-ai-card="${esc(artifactId)}" ${artifactId?'':'disabled'}>应用到阅读卡（仅填充空字段）</button><span class="ai-hint">应用会保留已有人工内容，并创建历史版本。</span>`}</div>`;
}
function renderAiDeepRead(data, target){
 const a=data?.analysis||data||{};const method=a.method||{};const critical=a.critical_reading||{};const list=(value)=>Array.isArray(value)?value.map(item=>`<li>${esc(typeof item==='string'?item:JSON.stringify(item))}</li>`).join(''):(value?`<li>${esc(value)}</li>`:'<li>原文未说明</li>');
  const timing=data?.duration_ms?` · ${Math.round(Number(data.duration_ms)/1000)} 秒 · ${data.model_call_count||'?'} 次模型请求`:'';
  target.innerHTML=`<div class="ai-meta">全文精读 · ${esc(data?.page_count||'')} 页 · ${esc(data?.model||'模型')} · ${esc(fmtDate(data?.created_at,true))}${timing}</div>${data?.low_quality_pages?`<div class="ai-quality-warning">有 ${esc(data.low_quality_pages)} 个低质量或空白页，相关结论可能不完整，请重点核对 PDF。</div>`:''}<div class="ai-deep-overview">${esc(a.overview||'原文未说明')}</div><div class="ai-deep-grid"><div><b>研究问题与动机</b><p>${esc(a.research_question||'原文未说明')}</p><p>${esc(a.motivation||'原文未说明')}</p></div><div><b>方法流程</b><p>${esc(method.pipeline||'原文未说明')}</p><ul>${list(method.components)}</ul></div><div><b>主要发现</b><ul>${list(a.main_findings)}</ul></div><div><b>局限与风险</b><ul>${list(a.limitations)}</ul></div><div><b>批判性阅读</b><ul>${list(critical.weak_points)}</ul></div><div><b>复现信息</b><ul>${list((a.reproducibility||{}).missing_information)}</ul></div></div>${aiDeepStructuredPanel(data,a)}${(a.evidence_spans||[]).length?`<div class="ai-subtitle">文字证据锚点</div><div class="ai-evidence-list">${aiEvidenceRows(a.evidence_spans,'quote')}</div>`:''}${aiVisualPanel(data,a)}<div class="ai-hint">AI 推断会在正文中标注；公式、图表和图像结论请根据页面证据回到 PDF 核验。</div>`;
}
function aiJobLabel(job){return job?.job_type==='reading_card'?'阅读卡':'全文精读';}
function aiJobStatusText(job){return ({queued:'排队中',running:'运行中',success:'已完成',failed:'失败',cancelled:'已取消',interrupted:'上次运行中断'})[job?.status]||job?.status||'未知';}
function renderAiJobStatus(job){const target=$('#ai-job-status');if(!target||!job)return;const total=Number(job.progress_total||0),current=Math.min(total,Number(job.progress_current||0)),pct=total?Math.round(current/total*100):job.status==='success'?100:0;const tone=['failed','interrupted','cancelled'].includes(job.status)?'ai-error':job.status==='success'?'evaluation-status':'';target.innerHTML=`<div class="ai-job-line"><span class="${tone}"><b>${esc(aiJobLabel(job))} · ${esc(aiJobStatusText(job))}</b>${job.message?` · ${esc(job.message)}`:''}</span><span>${total?`${current}/${total} · ${pct}%`:''}${job.duration_ms?` · ${Math.round(Number(job.duration_ms)/1000)} 秒`:''}</span></div>${total&&job.status==='running'?`<div class="ai-job-progress"><i style="width:${pct}%"></i></div>`:''}${job.error?`<div class="ai-error">${esc(job.error)}</div>`:''}${['queued','running'].includes(job.status)?`<button class="button small" data-cancel-ai-job="${esc(job.id)}">取消任务</button>`:''}`;}
async function watchAiJob(paperId, jobId){
 if(aiJobPollers[paperId]?.jobId===jobId)return;
 if(aiJobPollers[paperId]?.timer)clearTimeout(aiJobPollers[paperId].timer);
 const state={jobId,timer:null};aiJobPollers[paperId]=state;
 const tick=async()=>{try{const job=await api(`/api/ai-jobs/${jobId}`);renderAiJobStatus(job);if(['queued','running'].includes(job.status)){state.timer=setTimeout(tick,1500);return;}delete aiJobPollers[paperId];if(job.status==='success'){await loadAiAnalysis(paperId);if(job.job_type==='reading_card'&&$('.modal-backdrop')){await refresh();await openPaper(paperId);}toast(`${aiJobLabel(job)}已完成`);}else if(job.status==='failed'){toast(`${aiJobLabel(job)}失败：${job.error||'请查看任务详情'}`,'error');}}catch(err){state.timer=setTimeout(tick,3000);}};
 tick();
}
async function loadAiJobs(id){const target=$('#ai-job-status');if(!target)return;try{const data=await api(`/api/papers/${id}/ai-jobs?limit=10`);const jobs=data.jobs||[];const active=jobs.find(job=>['queued','running'].includes(job.status));const latest=active||jobs[0];if(latest)renderAiJobStatus(latest);else target.textContent='还没有后台 AI 任务';if(active)watchAiJob(id,active.id);}catch(e){target.textContent=`任务状态读取失败：${e.message}`;}}
async function loadAiAnalysis(id){
 const target=$('#full-ai-history');if(!target)return;try{const data=await api(`/api/papers/${id}/ai-analysis?limit=10`);const rows=data.analyses||[];rows.forEach(item=>aiAnalyses[item.id]=item);const card=rows.find(item=>item.artifact_type==='reading_card_draft');const deep=rows.find(item=>item.artifact_type==='deep_read');if(card){aiDrafts[id]={...card,draft:card.analysis?.reading_card||card.analysis};renderAiReadingCard(aiDrafts[id],$('#ai-reading-result'));}if(deep){aiDeepReads[id]={...deep};renderAiDeepRead(aiDeepReads[id],$('#ai-deep-result'));}target.innerHTML=rows.length?`<div>全文分析历史 · ${rows.length} 份</div><div class="ai-history-buttons">${rows.map(item=>`<button class="button small" data-show-ai-analysis="${esc(item.id)}">${item.artifact_type==='reading_card_draft'?'阅读卡':'精读'} · ${esc(fmtDate(item.created_at,true))}</button>`).join('')}</div>`:'尚未生成全文分析';}catch(e){target.textContent=`历史分析读取失败：${e.message}`;}}
function addFullAiAnalysisControls(id){
 const body=$('.modal-body');if(!body||body.querySelector('.full-ai-analysis'))return;
  const section=document.createElement('section');section.className='full-ai-analysis';section.innerHTML=`<div class="modal-section-title">全文 AI 分析</div><div class="agent-banner ai-full-banner" style="margin:0"><span class="agent-spark">✦</span><div><b>多模态阅读卡 + 深度精读</b><p>系统会提取逐页文字并渲染页面图像，让视觉模型检查公式、表格、曲线、流程图和截图；每条结论保留页码证据，扫描版或空页会显示质量警告。</p></div></div><label class="check-label ai-consent-label"><input id="full-ai-consent" type="checkbox"> 我同意将该论文全文文本和页面图像发送到已配置的模型服务</label><div class="ai-control-row"><button class="button small" data-ai-reading-card="${esc(id)}" ${agentConfigured?'':'disabled'}>自动生成阅读卡</button><button class="button small primary" data-ai-deep-read="${esc(id)}" ${agentConfigured?'':'disabled'}>开始多模态 AI 精读</button><span class="ai-hint">${agentConfigured?'模型已配置，可开始分析':'请先在系统设置配置模型'}</span></div><div id="ai-job-status" class="ai-job-status">正在读取后台任务…</div><div id="full-ai-history" class="ai-history-line">正在读取历史分析…</div><div id="ai-reading-result" class="ai-result"></div><div id="ai-deep-result" class="ai-result"></div>`;body.append(section);loadAiAnalysis(id);loadAiJobs(id);
}

async function loadReferences(id){
 try{const data=await api(`/api/papers/${id}/references`);const target=$('#citation-list');if(!target)return;target.innerHTML=data.count?data.references.map(r=>`<div class="source-line"><span>${esc(r.target_external_id)}</span><span>${esc(r.provider)} · ${fmtDate(r.last_seen_at,true)}</span></div>`).join(''):'尚未保存引用线索';}
 catch(e){const target=$('#citation-list');if(target)target.textContent=e.message;}
}

async function loadConnections(id){
 try{const data=await api(`/api/papers/${id}/connections`);const target=$('#connection-list');if(!target)return;const topics=(data.topics||[]).filter(item=>item.score>0).slice(0,5);const related=(data.related||[]).slice(0,5);target.innerHTML=(topics.length?`<div class="connection-group"><b>主题关联</b>${topics.map(item=>`<div class="connection-line"><span>${esc(item.name)}</span><span class="connection-tier ${item.tier==='高相关'?'high':item.tier==='邻近方向'?'near':''}">${esc(item.tier)} · ${item.score}</span></div>`).join('')}</div>`:'<div class="connection-group">尚未命中已保存主题</div>')+(related.length?`<div class="connection-group"><b>馆藏相近论文</b>${related.map(item=>`<div class="connection-line"><span class="connection-title" data-open-paper="${item.id}">${esc(item.title)}</span><span>${esc(item.tier)} · ${item.score}</span></div>`).join('')}</div>`:'');}
 catch(e){const target=$('#connection-list');if(target)target.textContent=e.message;}
}

function extractionQualityLabel(value){return value==='good'?'可检索':value==='low'?'低质量':'空页';}
function pageSnippet(text, query){const value=String(text||'');const needle=String(query||'').toLowerCase();const at=needle?value.toLowerCase().indexOf(needle):-1;if(at<0)return value.slice(0,240);return `${at>0?'…':''}${value.slice(Math.max(0,at-90),Math.min(value.length,at+String(query).length+150))}${at+String(query).length+150<value.length?'…':''}`;}
function renderPageSearchResults(target, data){const pages=data.pages||[];target.innerHTML=pages.length?pages.map(page=>`<div class="evidence-result"><div class="evidence-result-head"><b>第 ${page.page_number} 页</b><span class="evidence-quality ${page.quality}">${extractionQualityLabel(page.quality)} · ${page.char_count} 字</span></div><p>${esc(page.snippet||'')}</p><small>文本哈希 ${esc(String(page.text_sha256||'').slice(0,12))}…</small></div>`).join(''):'<div class="evidence-empty">没有命中已提取文本；可以换一个术语，或先运行文本提取。</div>';}
async function searchDocumentPages(id, query){const target=$('#page-search-results');if(!target)return;target.innerHTML='<span class="spinner"></span> 正在检索页码…';try{const data=await api(`/api/papers/${id}/pages?q=${encodeURIComponent(query)}&limit=20`);renderPageSearchResults(target,data);}catch(e){target.textContent=e.message;}}
async function loadExtraction(id){const target=$('#extraction-panel');if(!target)return;try{const data=await api(`/api/papers/${id}/extraction`);const pages=data.pages||[];target.innerHTML=`<div class="extraction-summary"><span>附件 ${data.attachment_count||0}</span><span>已提取 ${data.extracted_attachment_count||0}</span><span>页数 ${data.page_count||0}</span><span>字符 ${data.characters||0}</span></div><div class="extraction-quality">${pages.map(item=>`<span>${esc(String(item.attachment_id).slice(0,8))} · ${item.good_pages||0} 可检索 · ${item.low_pages||0} 低质量 · ${item.empty_pages||0} 空页</span>`).join('')||'尚未提取本地 PDF'}</div><div class="extraction-actions"><button class="button small" data-extract-paper="${id}" ${data.attachment_count?'':'disabled'}>提取 / 重新提取</button><form class="page-search-form" data-extraction-search="${id}"><input class="field-input" name="q" placeholder="检索原文术语，如 benchmark" ${data.page_count?'':'disabled'}><button class="button small" type="submit" ${data.page_count?'':'disabled'}>检索页码</button></form></div><div id="page-search-results" class="page-search-results"><div class="evidence-empty">提取后可按术语定位到页码和原文片段。</div></div>`;}catch(e){target.textContent=e.message;}}
async function expandPaper(id){const target=$('#expansion-result');const button=$(`[data-expand-paper="${CSS.escape(id)}"]`);if(target)target.innerHTML='<span class="spinner"></span> 正在沿引用网络扩展…';if(button){button.disabled=true;button.textContent='扩展中…';}try{const data=await api(`/api/papers/${id}/expand`,{method:'POST',body:jsonBody({limit:24})});if(target)target.innerHTML=`<div class="evidence-result"><b>已发现 ${data.count} 条关系</b><p>新增 ${data.created} 篇，已有记录 ${data.duplicates} 篇。它们已经进入文献库，可在“新发现/待读”中继续分诊。</p>${(data.candidates||[]).slice(0,8).map(item=>`<div class="connection-line"><span>${esc(item.title)}</span><span>${esc(item.relation)}</span></div>`).join('')}</div>`;await refresh();}catch(e){if(target)target.textContent=e.message;}finally{if(button){button.disabled=false;button.textContent='扩展引用、被引与相似论文';}}}

function importModal(){openModal(`<div class="modal-head"><div><h3>导入已有文献</h3><p>支持 BibTeX、RIS、CSL JSON / 本平台 JSON。导入会按 DOI、arXiv ID 和规范题名做保守去重。</p></div><button class="close-button" data-close-modal>×</button></div><div class="modal-body"><div class="form-field"><label>选择导出文件</label><input class="field-input" style="height:auto;padding:12px" id="import-file" type="file" accept=".bib,.bibtex,.ris,.json,application/json,text/plain"><span class="form-help">导入不会覆盖你已保存的笔记、状态或标签。大文件建议先拆分。</span></div><div id="import-status" style="margin-top:12px;font-size:10px;color:#748178"></div><div class="modal-section-title">完整备份恢复</div><p style="font-size:9px;line-height:1.7;color:#87938a;margin:0 0 9px">恢复会替换当前文献库。系统会先在本机备份当前数据库；请确认所选文件是本平台创建的 ZIP 备份。单个上传请求上限约 270 MB。</p><input class="field-input" style="height:auto;padding:11px" id="restore-file" type="file" accept=".zip,application/zip"><button class="button" style="margin-top:8px" data-action="restore-backup">校验并恢复备份</button></div><div class="modal-foot"><button class="button" data-close-modal>完成</button></div>`);}

function agentConfigModal(){api('/api/settings/model').then(s=>{agentConfigured=s.api_key_set&&s.enabled;openModal(`<div class="modal-head"><div><h3>模型配置中心</h3><p>通用供应商配置：官网用于识别，API 请求地址用于实际调用；支持 Chat Completions 与 Responses。</p></div><button class="close-button" data-close-modal>×</button></div><form id="model-settings-form"><div class="modal-body"><div class="form-grid"><div class="form-field"><label>供应商名称</label><input class="field-input" name="provider" value="${esc(s.provider||'')}" placeholder="任意供应商名称"></div><div class="form-field"><label>官网链接（可选）</label><input class="field-input" name="website_url" value="${esc(s.website_url||'')}" placeholder="https://example.com"></div><div class="form-field full"><label>Base URL（可选，服务根地址）</label><input class="field-input" name="base_url" value="${esc(s.base_url||'')}" placeholder="https://api.example.com/v1"><span class="form-help">可只填写下面的 API 请求地址；两者至少填写一个。</span></div><div class="form-field full"><label>API 请求地址（可选，完整 POST 端点）</label><input class="field-input" name="api_url" value="${esc(s.api_url||'')}" placeholder="https://api.example.com/v1/chat/completions"><span class="form-help">填写后会原样调用，支持供应商自定义路径；留空时才根据 Base URL 自动拼接协议路径。</span></div><div class="form-field"><label>协议</label><select class="field-input" name="protocol"><option value="chat_completions" ${s.protocol!=='responses'?'selected':''}>Chat Completions</option><option value="responses" ${s.protocol==='responses'?'selected':''}>Responses</option></select></div><div class="form-field"><label>Model</label><input class="field-input" name="model" value="${esc(s.model||'')}" placeholder="模型 ID" required></div><div class="form-field"><label>Temperature</label><input class="field-input" name="temperature" type="number" min="0" max="2" step="0.1" value="${s.temperature??0.2}"></div><div class="form-field full"><label>API Key</label><input class="field-input" name="api_key" type="password" placeholder="${s.api_key_set?'已配置，留空表示保持不变':'填写 API Key'}" autocomplete="off"><span class="form-help">当前来源：${esc(s.api_key_source||'未配置')}。密钥不会回显。</span><label class="check-label" style="margin-top:8px"><input type="checkbox" name="persist_api_key" ${s.api_key_source==='环境变量'?'':'checked'}> 保存到本地密钥文件，服务更新或重启后自动读取</label><label class="check-label" style="margin-top:6px"><input type="checkbox" name="clear_api_key"> 清除本地密钥（API Key 留空时生效）</label></div><div class="form-field full"><label class="check-label"><input type="checkbox" name="enabled" ${s.enabled?'checked':''}> 启用模型助读</label></div></div><div id="model-config-status" style="margin-top:12px;font-size:10px;color:#748178"></div></div><div class="modal-foot"><button class="button" type="button" data-model-test>测试连接</button><button class="button" type="button" data-close-modal>取消</button><button class="button primary" type="submit">保存配置</button></div></form>`,true);}).catch(e=>toast(e.message,'error'));}

async function createBackup(){try{toast('正在生成并校验备份…');const b=await api('/api/backup',{method:'POST',body:'{}'});const a=document.createElement('a');a.href=b.download_url;a.download=b.filename;document.body.append(a);a.click();a.remove();toast(`备份已生成：${b.filename}`);}catch(e){toast(e.message,'error');}}

async function saveReadingCard(id,button){const updates={};$$('[data-reading-field]',button.closest('.reading-card-section')||$('#modal-root')).forEach(field=>updates[field.dataset.readingField]=field.value);try{const card=await api(`/api/papers/${id}/reading-card`,{method:'PUT',body:jsonBody(updates)});const paper=papers.find(item=>item.id===id);if(paper)paper.reading_card=card;analytics=null;await refresh();if($('#modal-root').innerHTML)await openPaper(id);else if(activeView==='reading')renderView();toast(`阅读卡已保存 · 完成 ${card.completion_pct}%`);}catch(err){toast(err.message,'error');}}

async function updateSelectedPapers(updates){const ids=[...selectedLibraryIds];if(!ids.length)return;try{const result=await api('/api/papers/batch',{method:'POST',body:jsonBody({ids,updates})});selectedLibraryIds.clear();await refresh();analytics=null;toast(`已更新 ${result.updated} 篇${result.skipped?.length?`，跳过 ${result.skipped.length} 篇不存在的记录`:''}`);}catch(err){toast(err.message,'error');}}

async function showRunDetail(id){try{const run=await api(`/api/runs/${id}`);const status=run.status==='success'?'完成':run.status==='partial'?'部分失败':run.status==='running'?'运行中':'失败';const sourceRows=(run.source_details||[]).map(source=>`<section class="run-detail-source"><div class="section-heading" style="margin:0 0 8px"><b>${esc(SOURCE_NAME[source.source]||source.source)}</b><span class="log-state ${source.status==='ok'?'':'failed'}">${source.status==='ok'?'成功':'失败'}</span></div><div class="evaluation-grid"><div><small>抓取</small><b>${source.fetched??'—'}</b></div><div><small>过滤</small><b>${source.filtered??'—'}</b></div><div><small>候选</small><b>${source.accepted??'—'}</b></div><div><small>新增 / 重复</small><b>${source.new??'—'} / ${source.duplicates??'—'}</b></div></div>${source.error?`<p class="run-detail-error">${esc(source.error)}</p>`:''}${(source.variants||[]).length?`<div class="modal-section-title">检索变体</div>${source.variants.map(v=>`<div class="source-line"><span><b>${esc(v.kind||v.id||'检索式')}</b> · ${esc(v.query||'')}</span><span>${v.fetched??0} 抓取 · ${v.accepted??0} 候选</span></div>`).join('')}`:''}</section>`).join('')||'<div class="empty-state" style="padding:18px">旧版运行未保存来源级详情。</div>';openModal(`<div class="modal-head"><div><h3>检索运行详情</h3><p>${esc(run.query_name||'研究主题')} · ${fmtDate(run.started_at,true)} · ${status}</p></div><button class="close-button" data-close-modal>×</button></div><div class="modal-body"><div class="evaluation-grid"><div><small>新增</small><b>${run.new_count||0}</b></div><div><small>重复</small><b>${run.duplicate_count||0}</b></div><div><small>耗时</small><b>${run.started_at&&run.completed_at?`${Math.max(0,Math.round((new Date(run.completed_at)-new Date(run.started_at))/1000))} 秒`:'—'}</b></div><div><small>数据质量</small><b>${run.data_quality==='complete'?'来源详情完整':'历史详情缺失'}</b></div></div>${run.query?.query?`<div class="modal-section-title">检索问题</div><p style="font-size:10px;line-height:1.7;color:#66756b">${esc(run.query.query)}</p>`:''}<div class="modal-section-title">来源与查询路径</div>${sourceRows}</div><div class="modal-foot"><button class="button" data-close-modal>关闭</button></div>`);}catch(err){toast(err.message,'error');}}

async function showPaperHistory(id){try{const data=await api(`/api/papers/${id}/history`);const rows=(data.revisions||[]).map(item=>{const content=item.content||{};const preview=item.revision_type==='notes'?(content.notes||''):(content.research_question||content.contribution||'阅读卡快照');return `<div class="source-line" style="align-items:flex-start;gap:10px"><div><b>${item.revision_type==='notes'?'个人笔记':'结构化阅读卡'}</b><small style="display:block;color:#94a098;margin-top:3px">${fmtDate(item.created_at,true)} · ${esc(item.source||'user')}</small><span style="display:block;margin-top:5px;max-width:430px;white-space:pre-wrap">${esc(preview.slice(0,260))}</span></div><button class="button small" data-restore-revision="${item.id}" data-restore-paper="${id}">恢复</button></div>`}).join('')||'<div class="empty-state" style="padding:18px">还没有保存过历史版本。</div>';openModal(`<div class="modal-head"><div><h3>论文历史版本</h3><p>恢复会创建新的版本记录，现有历史不会被删除。</p></div><button class="close-button" data-close-modal>×</button></div><div class="modal-body">${rows}</div><div class="modal-foot"><button class="button" data-close-modal>关闭</button></div>`);}catch(err){toast(err.message,'error');}}

document.addEventListener('click',async e=>{
 const nav=e.target.closest('[data-nav]');if(nav){setView(nav.dataset.nav);return;}
 const navItem=e.target.closest('.nav-item[data-view]');if(navItem){setView(navItem.dataset.view);return;}
 if(e.target.closest('[data-dismiss-modal]')&&e.target.classList.contains('modal-backdrop')){closeModal();return;}
 if(e.target.closest('[data-close-modal]')){closeModal();return;}
 const open=e.target.closest('[data-open-paper]');if(open){await openPaper(open.dataset.openPaper);return;}
 const action=e.target.closest('[data-action]')?.dataset.action;
  if(action==='add-paper'){addPaperModal();return;}if(action==='add-query'){addQueryModal();return;}if(action==='import'){importModal();return;}if(action==='backup'){createBackup();return;}if(action==='agent-config'){agentConfigModal();return;}if(action==='refresh-analytics'){analytics=null;renderView();return;}if(action==='refresh-settings'){settingsSnapshot=null;renderView();return;}
  if(action==='save-backup-policy'){const button=e.target.closest('[data-action="save-backup-policy"]');button.disabled=true;try{settingsSnapshot.backupPolicy=await api('/api/settings/backup-policy',{method:'PATCH',body:jsonBody({enabled:$('#backup-enabled')?.checked===true,interval_hours:Number($('#backup-interval')?.value),retention:Number($('#backup-retention')?.value)})});settingsSnapshot.maintenance=await api('/api/maintenance/status');renderView();toast('自动备份设置已保存');}catch(err){toast(err.message,'error');}finally{if(button.isConnected)button.disabled=false;}return;}
  if(action==='rebuild-search-index'){try{const result=await api('/api/maintenance/rebuild-search-index',{method:'POST',body:'{}'});settingsSnapshot=null;renderView();toast(`全文索引已重建：${result.documents} 篇`);}catch(err){toast(err.message,'error');}return;}
 if(action==='restore-backup'){await restoreBackup();return;}
  if(e.target.closest('[data-library-load-more]')){await loadLibraryPage(false);return;}
 const runDetail=e.target.closest('[data-run-detail]');if(runDetail){await showRunDetail(runDetail.dataset.runDetail);return;}
  const history=e.target.closest('[data-paper-history]');if(history){await showPaperHistory(history.dataset.paperHistory);return;}
  const restoreRevision=e.target.closest('[data-restore-revision]');if(restoreRevision){if(!confirm('恢复此版本会替换当前笔记或阅读卡，并保存一条新的历史记录。继续吗？'))return;try{await api(`/api/papers/${restoreRevision.dataset.restorePaper}/history/${restoreRevision.dataset.restoreRevision}/restore`,{method:'POST',body:'{}'});closeModal();await refresh();await openPaper(restoreRevision.dataset.restorePaper);toast('历史版本已恢复');}catch(err){toast(err.message,'error');}return;}
 const saveCard=e.target.closest('[data-save-reading-card]');if(saveCard){await saveReadingCard(saveCard.dataset.saveReadingCard,saveCard);return;}
 const libraryCheck=e.target.closest('[data-library-check]');if(libraryCheck){if(libraryCheck.checked)selectedLibraryIds.add(libraryCheck.dataset.libraryCheck);else selectedLibraryIds.delete(libraryCheck.dataset.libraryCheck);renderView();return;}
  const selectAll=e.target.closest('[data-library-select-all]');if(selectAll){(libraryPage.items||[]).forEach(p=>selectAll.checked?selectedLibraryIds.add(p.id):selectedLibraryIds.delete(p.id));renderView();return;}
 const batch=e.target.closest('[data-batch-action]');if(batch){const actionName=batch.dataset.batchAction;if(actionName==='favorite')await updateSelectedPapers({is_favorite:true});else if(actionName==='topic'){const topic=$('.batch-topic')?.value?.trim();if(!topic){toast('请先填写批量主题','error');return;}await updateSelectedPapers({topic});}else await updateSelectedPapers({status:actionName});return;}
 const run=e.target.closest('[data-run-query]');if(run){runSavedQuery(run.dataset.runQuery);return;}
 const toggle=e.target.closest('[data-toggle-query]');if(toggle){try{await api(`/api/queries/${toggle.dataset.toggleQuery}`,{method:'PATCH',body:jsonBody({active:toggle.dataset.active==='1'})});await refresh();toast(toggle.dataset.active==='1'?'主题追踪已启用':'主题追踪已暂停');}catch(err){toast(err.message,'error');}return;}
 const qrun=e.target.closest('[data-query-run]');if(qrun){runSavedQuery(qrun.dataset.queryRun);return;}
 const selectPaper=e.target.closest('[data-select-paper]');if(selectPaper){selectedPaperId=selectPaper.dataset.selectPaper;renderView();return;}
  const openFavorite=e.target.closest('[data-favorite]');if(openFavorite){const p=(libraryPage.items||[]).find(x=>x.id===openFavorite.dataset.favorite)||papers.find(x=>x.id===openFavorite.dataset.favorite);if(p){await api(`/api/papers/${p.id}`,{method:'PATCH',body:jsonBody({is_favorite:!p.is_favorite})});await refresh();}return;}
 const statusBtn=e.target.closest('[data-status-paper]');if(statusBtn){try{await api(`/api/papers/${statusBtn.dataset.statusPaper}`,{method:'PATCH',body:jsonBody({status:statusBtn.dataset.status})});await refresh();toast(`已移入${STATUS[statusBtn.dataset.status]}`);}catch(err){toast(err.message,'error');}return;}
 const decision=e.target.closest('[data-query-decision]');if(decision){try{await api(`/api/queries/${decision.dataset.queryDecision}/matches/${decision.dataset.queryPaper}`,{method:'PATCH',body:jsonBody({user_decision:decision.dataset.decision,viewed:true})});const paper=discoveryResults.find(p=>p.id===decision.dataset.queryPaper);if(paper){paper.user_decision=decision.dataset.decision;paper.seen_before=true;paper.suppressed=decision.dataset.decision==='irrelevant';}renderView();toast(decision.dataset.decision==='irrelevant'?'已记住：此主题下不再重复推荐':'已记住：该论文与你的主题相关');}catch(err){toast(err.message,'error');}return;}
 const recommendation=e.target.closest('[data-recommendation-feedback]');if(recommendation){try{await api(`/api/papers/${recommendation.dataset.recommendationFeedback}/feedback`,{method:'POST',body:jsonBody({decision:recommendation.dataset.decision,scope:'global'})});await refresh();toast('已更新研究画像，后续会减少相似推荐');}catch(err){toast(err.message,'error');}return;}
 const modelTest=e.target.closest('[data-model-test]');if(modelTest){modelTest.disabled=true;modelTest.textContent='测试中…';try{const form=$('#model-settings-form');const f=new FormData(form);const value=Object.fromEntries(f.entries());value.enabled=f.get('enabled')==='on';value.persist_api_key=f.get('persist_api_key')==='on';value.clear_api_key=f.get('clear_api_key')==='on';await api('/api/settings/model',{method:'PATCH',body:jsonBody(value)});const result=await api('/api/settings/model/test',{method:'POST',body:'{}'});$('#model-config-status').innerHTML=`<span style="color:#60866b">推理测试成功：${esc(result.model)} · ${esc(result.inference_url||result.base_url)}</span>`;}catch(err){$('#model-config-status').innerHTML=`<span style="color:#b75a53">${esc(err.message)}</span>`;}finally{modelTest.disabled=false;modelTest.textContent='测试连接';}return;}
 const savePaper=e.target.closest('[data-save-paper]');if(savePaper){const id=savePaper.dataset.savePaper;try{await api(`/api/papers/${id}`,{method:'PATCH',body:jsonBody({status:$('#detail-status')?.value,topic:$('#detail-topic')?.value||'',notes:$('#detail-notes')?.value||''})});await refresh();toast('阅读记录已保存');if($('#modal-root').innerHTML)await openPaper(id);}catch(err){toast(err.message,'error');}return;}
 const saveNote=e.target.closest('[data-save-note]');if(saveNote){try{await api(`/api/papers/${saveNote.dataset.saveNote}`,{method:'PATCH',body:jsonBody({notes:$('#reader-note')?.value||''})});await refresh();toast('阅读笔记已保存');}catch(err){toast(err.message,'error');}return;}
 const historicalAi=e.target.closest('[data-show-ai-analysis]');if(historicalAi){const item=aiAnalyses[historicalAi.dataset.showAiAnalysis];if(!item){toast('这条 AI 分析历史已不可用','error');return;}if(item.artifact_type==='reading_card_draft'){aiDrafts[$('.full-ai-analysis [data-ai-reading-card]')?.dataset.aiReadingCard||'']={...item,draft:item.analysis?.reading_card||item.analysis};renderAiReadingCard({...item,draft:item.analysis?.reading_card||item.analysis},$('#ai-reading-result'));}else renderAiDeepRead(item,$('#ai-deep-result'));return;}
 const runAgent=e.target.closest('[data-agent-brief]');if(runAgent){await requestAgentBrief(runAgent.dataset.agentBrief);return;}
 const autoCard=e.target.closest('[data-ai-reading-card]');if(autoCard){await requestAiReadingCard(autoCard.dataset.aiReadingCard);return;}
 const deepRead=e.target.closest('[data-ai-deep-read]');if(deepRead){await requestAiDeepRead(deepRead.dataset.aiDeepRead);return;}
 const cancelJob=e.target.closest('[data-cancel-ai-job]');if(cancelJob){cancelJob.disabled=true;try{const job=await api(`/api/ai-jobs/${cancelJob.dataset.cancelAiJob}/cancel`,{method:'POST',body:'{}'});renderAiJobStatus(job);toast('已请求取消任务');}catch(err){toast(err.message,'error');}return;}
 const applyAiCard=e.target.closest('[data-apply-ai-card]');if(applyAiCard){const id=$('.full-ai-analysis [data-ai-reading-card]')?.dataset.aiReadingCard;if(!id){toast('无法识别当前论文','error');return;}try{const result=await api(`/api/papers/${id}/apply-ai-reading-card`,{method:'POST',body:jsonBody({artifact_id:applyAiCard.dataset.applyAiCard,merge_empty:true})});const paper=papers.find(item=>item.id===id);if(paper)paper.reading_card=result.reading_card;toast('AI 阅读卡已应用：只填充空字段');await openPaper(id);}catch(err){toast(err.message,'error');}return;}
 const syncRefs=e.target.closest('[data-sync-references]');if(syncRefs){const id=syncRefs.dataset.syncReferences;syncRefs.disabled=true;syncRefs.textContent='同步中…';try{const result=await api(`/api/papers/${id}/references/sync`,{method:'POST',body:'{}'});await loadReferences(id);toast(`已保存 ${result.count} 条 OpenAlex 参考文献线索`);}catch(err){toast(err.message,'error');}finally{syncRefs.disabled=false;syncRefs.textContent='同步参考文献';}return;}
 const extract=e.target.closest('[data-extract-paper]');if(extract){const id=extract.dataset.extractPaper;extract.disabled=true;extract.textContent='提取中…';try{const result=await api(`/api/papers/${id}/extract`,{method:'POST',body:'{}'});toast(`已提取 ${result.page_count} 页原文文本`);await loadExtraction(id);}catch(err){toast(err.message,'error');}finally{const current=$(`[data-extract-paper="${CSS.escape(id)}"]`);if(current){current.disabled=false;current.textContent='提取 / 重新提取';}}return;}
 const expand=e.target.closest('[data-expand-paper]');if(expand){await expandPaper(expand.dataset.expandPaper);return;}
 const exp=e.target.closest('[data-export]');if(exp){window.location.href=exp.dataset.export==='bibtex'?'/api/export/bibtex':'/api/export/json';return;}
});

document.addEventListener('click',async e=>{
  const button=e.target.closest('[data-action="agent-search-plan"]');
  if(!button)return;
  const form=$('#discover-form');
  const query=String(form?.querySelector('[name="query"]')?.value||'').trim();
  const sources=$$('.search-options input[name="source"]:checked').map(input=>input.value);
  if(!query||!sources.length){toast('请先填写研究问题并选择来源','error');return;}
  button.disabled=true;button.textContent='规划中…';
  try{
    const options={search_depth:form.querySelector('[name="search_depth"]')?.value,discovery_mode:form.querySelector('[name="discovery_mode"]')?.value,expand_concepts:form.querySelector('[name="expand_concepts"]')?.checked!==false,expand_relations:form.querySelector('[name="expand_relations"]')?.checked===true};
    const plan=await api('/api/discover/agent-plan',{method:'POST',body:jsonBody({query,sources,options})});
    discoveryMeta={plan};window.__discoveryDraftQuery=query;$('#global-search').value=query;renderView();
    toast(plan.ai_expansion?.enabled?`AI 已提出 ${plan.ai_expansion.added||0} 条待确认检索表达`:'已生成本地扩展检索计划');
  }catch(err){toast(err.message,'error');}finally{const current=$('[data-action="agent-search-plan"]');if(current){current.disabled=false;current.textContent='✦ AI 拓展检索';}}
});

document.addEventListener('submit',async e=>{
 if(e.target.matches('[data-extraction-search]')){e.preventDefault();const id=e.target.dataset.extractionSearch;const query=String(new FormData(e.target).get('q')||'').trim();if(!query){toast('请输入原文检索词','error');return;}await searchDocumentPages(id,query);return;}
 if(e.target.id==='model-settings-form'){e.preventDefault();const f=new FormData(e.target);const value=Object.fromEntries(f.entries());value.enabled=f.get('enabled')==='on';value.persist_api_key=f.get('persist_api_key')==='on';value.clear_api_key=f.get('clear_api_key')==='on';try{const saved=await api('/api/settings/model',{method:'PATCH',body:jsonBody(value)});agentConfigured=saved.api_key_set&&saved.enabled;settingsSnapshot=null;closeModal();toast(saved.api_key_set?`模型配置已保存 · ${saved.api_key_source||'已配置'}`:'模型参数已保存，尚未配置 API Key');}catch(err){$('#model-config-status').innerHTML=`<span style="color:#b75a53">保存失败：${esc(err.message)}</span>`;}return;}
 if(e.target.id==='add-paper-form'){e.preventDefault();const f=new FormData(e.target);const p=Object.fromEntries(f.entries());p.tags=p.tags||'';try{const result=await api('/api/papers',{method:'POST',body:jsonBody(p)});closeModal();await refresh();toast(result.created?'论文已加入文献库':'识别为已有记录，来源已合并');if(result.created)await openPaper(result.id);}catch(err){toast(err.message,'error');}return;}
 if(e.target.id==='add-query-form'){e.preventDefault();const f=new FormData(e.target);const sources=f.getAll('source');const search_options={author:f.get('author'),venue:f.get('venue'),exclude_terms:f.get('exclude_terms'),year_from:f.get('year_from'),year_to:f.get('year_to'),work_type:f.get('work_type'),sort:f.get('sort'),search_depth:f.get('search_depth'),discovery_mode:f.get('discovery_mode'),expand_concepts:f.get('expand_concepts')==='on',expand_relations:f.get('expand_relations')==='on',suppress_seen:f.get('suppress_seen')==='on'};try{await api('/api/queries',{method:'POST',body:jsonBody({name:f.get('name'),query:f.get('query'),sources,search_options,cadence_hours:Number(f.get('cadence'))})});closeModal();await refresh();setView('automation');toast('主题已保存，首次同步正在后台启动');}catch(err){toast(err.message,'error');}return;}
 if(e.target.id==='discover-form'){e.preventDefault();const f=new FormData(e.target);const query=String(f.get('query')||'').trim();const sources=$$('.search-options input[name="source"]:checked').map(input=>input.value);if(!sources.length){toast('请至少选择一个来源','error');return;}const options={author:f.get('author'),venue:f.get('venue'),exclude_terms:f.get('exclude_terms'),year_from:f.get('year_from'),year_to:f.get('year_to'),work_type:f.get('work_type'),sort:f.get('sort'),search_depth:f.get('search_depth'),discovery_mode:f.get('discovery_mode'),expand_concepts:f.get('expand_concepts')==='on',expand_relations:f.get('expand_relations')==='on',suppress_seen:f.get('suppress_seen')==='on'};const btn=e.target.querySelector('button[type="submit"]');btn.disabled=true;btn.innerHTML='<span class="spinner"></span> 正在检索';try{discoveryQuery=query;activeDiscoveryRunId=newRequestId();discoveryResults=[];discoveryMeta={id:activeDiscoveryRunId,status:'running',query,query_name:query,source_names:sources,papers:[]};persistUiState();const result=await api('/api/discover',{method:'POST',body:jsonBody({query,sources,limit:25,options,request_id:activeDiscoveryRunId})});activeDiscoveryRunId=result.id||activeDiscoveryRunId;discoveryMeta={...discoveryMeta,...result};persistUiState();await refresh();setView('discover');watchDiscoveryRun(activeDiscoveryRunId);toast('检索已加入后台；刷新后会继续显示进度和结果');}catch(err){toast(err.message,'error');}finally{const current=$('#discover-form button[type="submit"]');if(current){current.disabled=false;current.innerHTML='<span>⌕</span> 搜索论文';}}}
});

document.addEventListener('change',async e=>{
 if(e.target.id==='library-status'){libraryStatus=e.target.value;loadLibraryPage(true);return;}
 if(e.target.id==='library-topic'){libraryTopic=e.target.value;loadLibraryPage(true);return;}
 if(e.target.id==='library-sort'){librarySort=e.target.value;loadLibraryPage(true);return;}
 if(e.target.id==='library-favorite'){libraryFavorite=e.target.checked;loadLibraryPage(true);return;}
 if(e.target.id==='library-has-card'){libraryHasCard=e.target.checked;loadLibraryPage(true);return;}
 if(e.target.matches('.batch-status')){if(e.target.value)await updateSelectedPapers({status:e.target.value});return;}
 if(e.target.matches('[data-paper-status]')){try{await api(`/api/papers/${e.target.dataset.paperStatus}`,{method:'PATCH',body:jsonBody({status:e.target.value})});await refresh();selectedPaperId=e.target.dataset.paperStatus;renderView();toast('阅读状态已更新');}catch(err){toast(err.message,'error');}return;}
 if(e.target.matches('[data-select-paper]')){selectedPaperId=e.target.dataset.selectPaper;renderView();return;}
 if(e.target.matches('[data-attach-paper]')){await attachPdf(e.target.dataset.attachPaper,e.target.files?.[0]);return;}
 if(e.target.id==='import-file'&&e.target.files?.[0]){await importFile(e.target.files[0]);return;}
});

let libraryTimer=null;
document.addEventListener('input',e=>{
 if(e.target.id==='library-filter'){libraryQuery=e.target.value;clearTimeout(libraryTimer);libraryTimer=setTimeout(()=>loadLibraryPage(true,true),240);}
 if(e.target.id==='global-search'){const value=e.target.value;if(value.trim()){libraryQuery=value;activeView='library';$$('.nav-item[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view==='library'));$('#crumb-current').textContent='文献库';loadLibraryPage(true);}}
});
$('#global-search').addEventListener('keydown',e=>{if(e.key==='Enter'){libraryQuery=e.target.value;setView('library');}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#global-search').focus();}});
$('#add-topic-shortcut').addEventListener('click',addQueryModal);
$('#backup-shortcut').addEventListener('click',createBackup);
$('#help-button').addEventListener('click',()=>toast(`本地资料目录：${appState?.data_dir||'正在读取'}`));

async function runSavedQuery(id){const btn=$(`[data-run-query="${CSS.escape(id)}"]`);if(btn){btn.disabled=true;btn.textContent='同步中…';}try{const r=await api(`/api/queries/${id}/run`,{method:'POST',body:'{}'});activeDiscoveryRunId=r.id;discoveryQuery=r.query||r.query_name||'';discoveryResults=r.papers||[];discoveryMeta=r;persistUiState();await refresh();setView('discover');watchDiscoveryRun(r.id);toast('主题检索已加入后台；进度和结果会在此页面持续更新');}catch(e){toast(e.message,'error');}finally{await refresh();}}
async function attachPdf(id,file){if(!file)return;if(file.size>100*1024*1024){toast('PDF 超过 100 MB 限制','error');return;}const reader=new FileReader();reader.onload=async()=>{try{const b64=String(reader.result).split(',')[1];await api(`/api/papers/${id}/attachment`,{method:'POST',body:jsonBody({filename:file.name,data:b64})});await refresh();toast('PDF 已保存到本机资料库');if($('#modal-root').innerHTML)await openPaper(id);else{selectedPaperId=id;setView('reading');}}catch(e){toast(e.message,'error');}};reader.readAsDataURL(file);}
async function importFile(file){const status=$('#import-status');status.textContent='正在读取并导入…';try{const content=await file.text();const ext=file.name.toLowerCase().split('.').pop();const format=ext==='bib'||ext==='bibtex'?'bibtex':ext==='ris'?'ris':'json';const result=await api('/api/import',{method:'POST',body:jsonBody({format,content})});status.innerHTML=`<span style="color:#60866b">完成：新增 ${result.imported} 篇 · 去重 ${result.duplicates} 篇 · 跳过错误 ${result.errors} 条</span>`;await refresh();toast('文献导入完成');}catch(e){status.innerHTML=`<span style="color:#b75a53">导入失败：${esc(e.message)}</span>`;}}
async function restoreBackup(){const file=$('#restore-file')?.files?.[0];if(!file){toast('请先选择本平台 ZIP 备份','error');return;}if(file.size>260*1024*1024){toast('备份包超过当前 260 MB 浏览器恢复上限；可手动替换本机数据目录','error');return;}if(!confirm('恢复会替换当前文献库，系统会先保存当前数据库副本。确定继续？'))return;try{const content=await file.arrayBuffer();let binary='';const bytes=new Uint8Array(content);for(let i=0;i<bytes.length;i+=0x8000)binary+=String.fromCharCode(...bytes.subarray(i,i+0x8000));const data=btoa(binary);const r=await api('/api/backup/restore',{method:'POST',body:jsonBody({filename:file.name,data})});closeModal();await refresh();toast(`备份恢复完成，附件 ${r.attachments_restored} 个`);}catch(e){toast(e.message,'error');}}
async function requestAgentBrief(id){const consent=$('#agent-consent')?.checked;if(!consent){toast('请先确认这篇论文摘要可以发送到模型服务','error');return;}const result=$('#agent-result');result.innerHTML='<div class="skeleton" style="height:48px"></div>';try{const data=await api(`/api/papers/${id}/agent-brief`,{method:'POST',body:jsonBody({consent:true})});result.innerHTML=`<div class="detail-item"><small>基于 ${esc(data.basis)} · ${esc(data.model)}</small><span style="white-space:pre-wrap;line-height:1.75;display:block">${esc(data.answer)}</span></div>`;}catch(e){result.innerHTML=`<div class="detail-item"><small>助读暂不可用</small><span>${esc(e.message)}</span></div>`;}}

async function requestAiReadingCard(id){
 if(!$('#full-ai-consent')?.checked){toast('请先确认全文可以发送到模型服务','error');return;}
 const target=$('#ai-reading-result'),button=$(`[data-ai-reading-card="${CSS.escape(id)}"]`);if(target)target.innerHTML='<div class="skeleton" style="height:56px"></div>';
 if(button){button.disabled=true;button.textContent='正在提取并分析全文…';}
 try{const data=await api(`/api/papers/${id}/ai-reading-card`,{method:'POST',body:jsonBody({background:true,consent:true,apply:true,merge_empty:true,template:'fulltext_reading_card',language:'zh-CN'})});if(data.job){renderAiJobStatus(data.job);watchAiJob(id,data.job.id);toast(data.deduplicated?'已有阅读卡任务在运行':'阅读卡任务已加入后台队列');return;}aiDrafts[id]=data;renderAiReadingCard(data,target);}
 catch(e){if(target)target.innerHTML=`<div class="ai-error">全文阅读卡生成失败：${esc(e.message)}</div>`;}
 finally{if(button){button.disabled=!agentConfigured;button.textContent='自动生成阅读卡';}}
}
async function requestAiDeepRead(id){
 if(!$('#full-ai-consent')?.checked){toast('请先确认全文可以发送到模型服务','error');return;}
 const target=$('#ai-deep-result'),button=$(`[data-ai-deep-read="${CSS.escape(id)}"]`);if(target)target.innerHTML='<div class="skeleton" style="height:56px"></div>';
 if(button){button.disabled=true;button.textContent='正在逐页精读…';}
 try{const data=await api(`/api/papers/${id}/ai-deep-read`,{method:'POST',body:jsonBody({background:true,consent:true,template:'graduate_deep_read',language:'zh-CN'})});if(data.job){renderAiJobStatus(data.job);watchAiJob(id,data.job.id);toast(data.deduplicated?'已有精读任务在运行':'精读任务已加入后台队列');return;}aiDeepReads[id]=data;renderAiDeepRead(data,target);}
 catch(e){if(target)target.innerHTML=`<div class="ai-error">AI 精读失败：${esc(e.message)}</div>`;}
 finally{if(button){button.disabled=!agentConfigured;button.textContent='开始 AI 精读全文';}}
}

